; rotate.asm -- chapter 10: the twelve shifts and rotates, bit by bit
; generated by gen10.py
        INCLUDE "msx.inc"
        OUTPUT "rotate.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; %10110010 put through each of the twelve shifts and rotates, once with
; the carry clear and once with it set: the byte bit by bit, and the carry
; after it (figure 10.2).
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 0
        ld c, 0
        ld hl, r0s
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the byte, and the carry clear
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the byte, and the carry set
        call show
        ld b, 2
        ld c, 0
        ld hl, r0
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the carry clear
        rlca                    ; the instruction shown
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the carry set
        rlca
        call show
        ld b, 3
        ld c, 0
        ld hl, r1
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the carry clear
        rrca                    ; the instruction shown
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the carry set
        rrca
        call show
        ld b, 4
        ld c, 0
        ld hl, r2
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the carry clear
        rla                     ; the instruction shown
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the carry set
        rla
        call show
        ld b, 5
        ld c, 0
        ld hl, r3
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the carry clear
        rra                     ; the instruction shown
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the carry set
        rra
        call show
        ld b, 7
        ld c, 0
        ld hl, r4
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the carry clear
        rlc a                   ; the instruction shown
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the carry set
        rlc a
        call show
        ld b, 8
        ld c, 0
        ld hl, r5
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the carry clear
        rrc a                   ; the instruction shown
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the carry set
        rrc a
        call show
        ld b, 9
        ld c, 0
        ld hl, r6
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the carry clear
        rl a                    ; the instruction shown
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the carry set
        rl a
        call show
        ld b, 10
        ld c, 0
        ld hl, r7
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the carry clear
        rr a                    ; the instruction shown
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the carry set
        rr a
        call show
        ld b, 11
        ld c, 0
        ld hl, r8
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the carry clear
        sla a                   ; the instruction shown
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the carry set
        sla a
        call show
        ld b, 12
        ld c, 0
        ld hl, r9
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the carry clear
        sra a                   ; the instruction shown
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the carry set
        sra a
        call show
        ld b, 13
        ld c, 0
        ld hl, r10
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the carry clear
        srl a                   ; the instruction shown
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the carry set
        srl a
        call show
        ld b, 14
        ld c, 0
        ld hl, r11
        call puts
        ld c, 6
        ld a, %10110010
        or a                    ; the carry clear
        sll a                   ; the instruction shown
        call show
        ld c, 18
        ld a, %10110010
        scf                     ; the carry set
        sll a
        call show
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; show: A bit by bit at row B from column C, and the carry as one box after
;       a gap. Keeps B.
show:   push af
        call fatbits            ; the eight bits of A; C moves on by 8
        inc c                   ; a gap
        pop af
        ld a, 1
        jr nc, sh1
        ld a, 2
sh1:    jp putc                 ; the carry, as one box
r0s:    db "START", 0
r0:     db "RLCA", 0
r1:     db "RRCA", 0
r2:     db "RLA", 0
r3:     db "RRA", 0
r4:     db "RLC A", 0
r5:     db "RRC A", 0
r6:     db "RL A", 0
r7:     db "RR A", 0
r8:     db "SLA A", 0
r9:     db "SRA A", 0
r10:     db "SRL A", 0
r11:     db "SLL A", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret

; fatbits: A = a byte, drawn as 8 boxes, bit 7 first: a filled box for 1,
;          an empty one for 0. B = row, C = column; C moves on by 8.
;          Uses A. Keeps HL.
fatbits:
        push hl
        ld l, a
        ld h, 8
.bit:   ld a, 1                 ; an empty box ...
        rl l                    ; the next bit, into the carry
        jr nc, .put
        ld a, 2                 ; ... or a filled one
.put:   call putc
        inc c
        dec h
        jr nz, .bit
        pop hl
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
